const D = { energy: .6, scale: 1, density: .55, speed: 1, heat: .55, fume: .5, hue: 24, x: .5, y: .46, style: 'pahoehoe', act: 'cooling', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 24;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

const STY = {
  // fresh black pahoehoe, orange-yellow incandescent cracks, ember-red sky
  pahoehoe:  { skT:[8,50,10], skB:[16,72,26], crust:[16,30,7], crustL:[20,40,14],
               hot:[26,95,99], hotC:[46,90,99], deep:[8,95,60], fume:[14,26,22], grain:16, mono:0, thermal:0 },
  // heavy night smoke, deep red glow, menacing
  nightfume: { skT:[350,52,7], skB:[6,70,18], crust:[350,24,6], crustL:[4,34,11],
               hot:[10,96,88], hotC:[24,92,96], deep:[356,96,46], fume:[356,22,16], grain:14, mono:0, thermal:0 },
  // sulfurous acid yellow-green volcanic gas
  sulfur:    { skT:[54,44,12], skB:[48,64,28], crust:[60,20,8], crustL:[56,30,15],
               hot:[50,96,99], hotC:[58,86,99], deep:[38,92,64], fume:[62,34,30], grain:18, mono:0, thermal:0 },
  // ABSTRACTED thermal false-colour ironbow, cracks as hot isotherms
  thermal:   { skT:[248,60,6], skB:[250,44,12], crust:[250,44,10], crustL:[268,44,20],
               hot:[40,90,99], hotC:[54,80,99], deep:[320,80,72], fume:[280,30,26], grain:6, mono:0, thermal:1 },
  // ABSTRACTED sumi ink: basalt plates in ink, white-hot crack network
  ink:       { skT:[30,6,8], skB:[30,4,16], crust:[30,8,7], crustL:[30,6,16],
               hot:[30,3,98], hotC:[30,2,99], deep:[30,6,60], fume:[30,4,26], grain:28, mono:1, thermal:0 }
};
const st = STY[P.style] || STY.pahoehoe;

const en = Math.max(0, Math.min(1, P.energy));
const heat = Math.max(0, Math.min(1, P.heat));
const hzY = height * P.y;                         // horizon
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.fumeB.remove(); }
  S.sky = mk(W, H); S.fumeB = mk(W, H);

  // sky: smoke-choked, ember glow low on the horizon
  const g = S.sky; g.noStroke();
  const cT = sh(st.skT), cB = sh(st.skB);
  for (let yy = 0; yy < Math.ceil(hzY); yy++) { const c = L3(cT, cB, Math.pow(yy / Math.max(1, hzY), .6)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }
  // dark basalt crust below, warming toward the foreground where more molten shows
  const crust = sh(st.crust), crustL = sh(st.crustL);
  for (let yy = Math.ceil(hzY); yy < H; yy++) {
    const f = (yy - hzY) / Math.max(1, H - hzY);
    const c = L3(L3(crust, cB, .5), crustL, f * .6);
    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }
  // plate mottling on the crust (cooled ropey texture) + a warm ambient wash near cracks
  g.noStroke();
  const np = Math.floor(120 + P.density * 160);
  for (let i = 0; i < np; i++) {
    const f = fr(i * 3 + 11);
    const py = hzY + Math.pow(f, .6) * (H - hzY);
    const px = fr(i * 3 + 12) * W;
    const pr = u * (.01 + fr(i * 3 + 13) * .05) * (.3 + (py - hzY) / (H - hzY));
    const c = L3(crust, crustL, fr(i * 3 + 14));
    g.fill(c[0], c[1], Math.max(2, c[2] + (fr(i) - .5) * 8), 30);
    g.ellipse(px, py, pr, pr * .5);
  }

  // --- crack network: meandering incandescent lines, perspective by depth ---
  S.cracks = [];
  const nc = Math.floor(7 + P.density * 12);
  for (let i = 0; i < nc; i++) {
    const depth = fr(i * 5 + 21);                 // 0 far (near horizon), 1 near (foreground)
    const y0 = hzY + Math.pow(depth, 1.3) * (H - hzY);
    const pts = []; let x = -u * .1, y = y0;
    const wig = u * (.01 + depth * .06);
    const seg = u * (.04 + depth * .05);
    const nWav = fr(i * 5 + 22) * 3 + 1;
    while (x < W + u * .1) {
      y = y0 + Math.sin(x * (.004 + depth * .006) + fr(i) * 6.3) * wig + Math.sin(x * .015 * nWav) * wig * .4;
      pts.push([x, y]); x += seg;
    }
    const w = u * (.004 + depth * .016) * P.scale;
    S.cracks.push({ pts: pts, w: w, depth: depth, phase: fr(i * 5 + 23) * 6.283, rate: .5 + fr(i) * 1.5,
                    bake: st.thermal ? 1 : (fr(i * 5 + 24) < .3 ? 1 : 0) });
    // bake a dark groove into the crust so cracks read even when the glow is low
    if (!st.mono) {
      g.strokeWeight(w * 1.6); g.stroke(crust[0], crust[1], Math.max(1, crust[2] - 4), 80); g.noFill();
      g.beginShape(); for (const p of pts) g.vertex(p[0], p[1]); g.endShape();
      g.noStroke();
    }
  }
  // skylights: bright molten holes
  S.slights = [];
  const nsl = Math.floor(2 + P.density * 5);
  for (let i = 0; i < nsl; i++) {
    const depth = .3 + fr(i * 7 + 41) * .7;
    S.slights.push({ x: fr(i * 7 + 42) * W, y: hzY + Math.pow(depth, 1.3) * (H - hzY),
                     r: u * (.02 + fr(i * 7 + 43) * .05) * depth * P.scale, phase: fr(i * 7 + 44) * 6.283, depth: depth });
  }

  // fume band (tileable) rising off the field
  const fumeC = sh(st.fume);
  S.fumeB.noStroke();
  for (let i = 0; i < 12; i++) {
    const bx = fr(i * 5 + 61) * W, by = fr(i * 5 + 62) * H;
    const bw = u * (.3 + fr(i * 5 + 63) * .8), bhh = u * (.06 + fr(i * 5 + 64) * .16);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.fumeB.fill(fumeC[0], fumeC[1] * (1 - kk * .1), Math.min(60, fumeC[2] + kk * 3), 6 * (1 - kk * .2));
      S.fumeB.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { cooling: { glow: .8 + .2 * Math.sin(K.t * .13), ember: 1, fume: 1 },
              breakout: { glow: 1.2 + .2 * Math.sin(K.t * .3 + sec), ember: 1.8, fume: 1.1 },
              crust: { glow: .5 + .12 * Math.sin(K.t * .09), ember: .6, fume: 1.6 } };
const act = ACT[P.act] || ACT.cooling;

noStroke();
image(S.sky, 0, 0);

// heat glow ambient near the foreground (lifts luminance off pure black)
const deepC = sh(st.deep), hotC = sh(st.hot), hotCore = sh(st.hotC);
blendMode(ADD);
const amb = (.4 + .6 * heat) * act.glow * (.7 + .3 * K.swell) + A.bass * .2;
for (let i = 0; i < 4; i++) {
  fill(deepC[0], deepC[1] * .8, deepC[2], (4 + 9 * amb * en) * (1 - i * .18));
  ellipse(width * P.x, height + u * .05, width * (.8 + i * .3), (height - hzY) * (.5 + i * .3));
}
blendMode(BLEND);

// ---------------- incandescent cracks (drawn live, pulsing) ----------------
for (const cr of S.cracks) {
  const pulse = (.5 + .5 * Math.sin(K.t * cr.rate * P.speed + cr.phase)) * .6 + .4;
  const advect = Math.sin(K.t * (.4 + cr.depth) + cr.phase * 2);   // heat travelling along the crack
  const bright = pulse * act.glow * (.5 + heat) * (.7 + .3 * en);
  // outer glow
  blendMode(ADD);
  for (let pass = 0; pass < 3; pass++) {
    const w = cr.w * (1 + pass * 2.2);
    const col = pass === 0 ? hotCore : (pass === 1 ? hotC : deepC);
    strokeWeight(w); noFill();
    stroke(col[0], col[1], col[2], (pass === 0 ? 70 : 26) * bright * (1 - pass * .15));
    beginShape();
    for (let j = 0; j < cr.pts.length; j++) {
      const p = cr.pts[j];
      const wob = Math.sin(j * .7 + K.t * (.6 + cr.depth) + cr.phase) * cr.w * .3;
      vertex(p[0], p[1] + wob);
    }
    endShape();
  }
  // travelling hot spots along the crack (advection)
  const nh = Math.floor(2 + cr.depth * 5);
  for (let h = 0; h < nh; h++) {
    const t = ((advect * .3 + h / nh + K.t * (.05 + cr.depth * .08) * P.speed) % 1 + 1) % 1;
    const idx = Math.floor(t * (cr.pts.length - 1));
    const p = cr.pts[idx];
    fill(hotCore[0], hotCore[1] * .6, hotCore[2], 70 * bright);
    ellipse(p[0], p[1], cr.w * 2.5, cr.w * 1.6);
  }
  blendMode(BLEND);
}

// skylights
blendMode(ADD);
for (const sl of S.slights) {
  const pulse = .6 + .4 * Math.sin(K.t * (.6 + sl.depth) * P.speed + sl.phase);
  for (let pass = 0; pass < 3; pass++) {
    const col = pass === 0 ? hotCore : (pass === 1 ? hotC : deepC);
    fill(col[0], col[1], col[2], (pass === 0 ? 80 : 22) * pulse * act.glow * (.5 + heat));
    ellipse(sl.x, sl.y, sl.r * (1 + pass * 2), sl.r * (.6 + pass * 1.2));
  }
}
blendMode(BLEND);

// ---------------- fume / smoke drifting up ----------------
const FW = S.fumeB.width;
const fx = ((-K.t * u * .006 * P.speed % FW) + FW) % FW;
const fy = ((-K.t * u * .012 * P.speed % S.fumeB.height) + S.fumeB.height) % S.fumeB.height;
push(); tint(0, 0, 100, 70 * (P.fume + .3) * act.fume); image(S.fumeB, fx - FW, fy - S.fumeB.height); image(S.fumeB, fx, fy - S.fumeB.height); image(S.fumeB, fx - FW, fy); image(S.fumeB, fx, fy); pop();

// ---------------- ember sparks rising ----------------
blendMode(ADD);
const ne = Math.floor((14 + P.density * 30) * act.ember);
for (let i = 0; i < ne; i++) {
  const life = ((K.t * (.06 + fr(i * 3 + 301) * .1) * P.speed + fr(i * 3 + 302)) % 1);
  const base = S.cracks.length ? S.cracks[i % S.cracks.length] : null;
  const bx = base ? base.pts[Math.floor(fr(i * 3 + 303) * (base.pts.length - 1))][0] : fr(i) * width;
  const by0 = base ? base.pts[Math.floor(fr(i * 3 + 303) * (base.pts.length - 1))][1] : height;
  const ex = bx + Math.sin(K.t * (1 + fr(i)) + i) * u * .02 + (fr(i) - .5) * u * .04;
  const ey = by0 - life * u * .35;
  fill(hotCore[0], hotCore[1] * .5, hotCore[2], 60 * (1 - life) * en);
  ellipse(ex, ey, u * .003 * (1 - life * .5), u * .003 * (1 - life * .5));
}
blendMode(BLEND);

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.crust[0], st.crust[1] * .4, fr(i * 3 + 403) > .5 ? 60 : 5, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.crust)[0], st.crust[1], 4, 22 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.crust)[0], st.crust[1] * .5, 4, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
